#include <stdio.h>
struct tag_ { int field_; };
enum enumtag_ { enumvalue_ = 41 };
int function_(struct tag_ *p) { return p->field_; }
int function_(struct tag_ *p) { int local_ = 1; return function_(p) + local_; }
static struct tag_ global_ = { enumvalue_ };
int main(void) {
    int (*callback_)(struct tag_ *) = function_;
    int result = callback_(&global_);
    printf("long names %d %d\n", result, function_(&global_));
    return result != 42 || function_(&global_) != 41;
}
